'Sections 12-24 data_room:grant'),('risk:read','Sections 12-24 risk:read'),('risk:write','Sections 12-24 risk:write'),('disputes:read','Sections 12-24 disputes:read'),('disputes:write','Sections 12-24 disputes:write'),('residential:read','Sections 12-24 residential:read'),('residential:write','Sections 12-24 residential:write'),('leasing:read','Sections 12-24 leasing:read'),('leasing:write','Sections 12-24 leasing:write'),('land:read','Sections 12-24 land:read'),('land:write','Sections 12-24 land:write'),('sales:read','Sections 12-24 sales:read'),('sales:write','Sections 12-24 sales:write'),('sales:approve','Sections 12-24 sales:approve'),('projects:read','Sections 12-24 projects:read'),('projects:write','Sections 12-24 projects:write'),('insurance:read','Sections 12-24 insurance:read'),('insurance:write','Sections 12-24 insurance:write'),('financing:read','Sections 12-24 financing:read'),('financing:write','Sections 12-24 financing:write'),('integrations:read','Sections 12-24 integrations:read'),('integrations:write','Sections 12-24 integrations:write'),('analytics:read','Sections 12-24 analytics:read') ON CONFLICT DO NOTHING;
-- +goose StatementBegin
CREATE FUNCTION business_s1224_uuidv7_seed() RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE t text;r text;
BEGIN t=lpad(to_hex(floor(extract(epoch FROM clock_timestamp())*1000)::bigint),12,'0');r=replace(gen_random_uuid()::text,'-','');RETURN (substring(t,1,8)||'-'||substring(t,9,4)||'-7'||substring(r,1,3)||'-8'||substring(r,4,3)||'-'||substring(r,7,12))::uuid;END;$$;
-- +goose StatementEnd
-- +goose StatementBegin
DO $$ DECLARE item record;next_role uuid;next_version bigint;permission_code text;
BEGIN
 FOR item IN SELECT m.id member_id,m.organisation_id,m.account_id,r.* FROM staff_memberships m JOIN organisations o ON o.id=m.organisation_id JOIN role_templates r ON r.id=m.role_id AND r.organisation_id=m.organisation_id JOIN business_accounts actor_account ON actor_account.id=m.account_id WHERE actor_account.status='ACTIVE' AND o.state IN ('DRAFT','KYB_PENDING','ACTIVE') AND m.kind='OWNER' AND m.status='ACTIVE' AND m.scope_kind='COMPANY' AND m.scope_id=m.organisation_id AND o.representative_account_id=m.account_id AND r.active AND r.name='Owner' AND m.effective_at<=now() AND (m.expires_at IS NULL OR m.expires_at>now()) AND EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_id=r.id AND rp.permission='roles:write') AND NOT EXISTS(SELECT 1 FROM staff_scope_grants denied WHERE denied.membership_id=m.id AND denied.capability='roles:write' AND denied.deny AND denied.revoked_at IS NULL AND denied.effective_at<=now() AND (denied.expires_at IS NULL OR denied.expires_at>now())) AND EXISTS(SELECT 1 FROM staff_scope_grants g WHERE g.membership_id=m.id AND g.capability='roles:write' AND g.scope_kind='COMPANY' AND g.scope_id=m.organisation_id AND g.inherit AND NOT g.deny AND g.revoked_at IS NULL AND g.expires_at IS NULL AND g.effective_at<=now())
 LOOP
 PERFORM 1 FROM organisations WHERE id=item.organisation_id FOR UPDATE;
 next_role=business_s1224_uuidv7_seed();SELECT max(version)+1 INTO next_version FROM role_templates WHERE organisation_id=item.organisation_id AND role_key=item.role_key;
 INSERT INTO role_templates(id,organisation_id,role_key,name,version,active,senior_emergency_eligible) VALUES(next_role,item.organisation_id,item.role_key,item.name,next_version,true,item.senior_emergency_eligible);
 INSERT INTO role_permissions(role_id,permission) SELECT next_role,permission FROM role_permissions WHERE role_id=item.id;
 FOR permission_code IN SELECT unnest(ARRAY['inbox:read','inbox:write','inbox:reply','inbox:configure','support:read','support:write','ai:read','ai:configure','automation:read','automation:write','automation:approve','reviews:read','reviews:write','reviews:moderate','quality:read','quality:write','reputation:read','leads:read','leads:write','campaigns:read','campaigns:write','campaigns:approve','brand:read','brand:write','storefront:publish','finance:read','finance:write','finance:approve','payouts:write','housekeeping:read','housekeeping:write','maintenance:read','maintenance:write','maintenance:approve','managers:read','managers:write','professional:read','professional:write','data_room:grant','risk:read','risk:write','disputes:read','disputes:write','residential:read','residential:write','leasing:read','leasing:write','land:read','land:write','sales:read','sales:write','sales:approve','projects:read','projects:write','insurance:read','insurance:write','financing:read','financing:write','integrations:read','integrations:write','analytics:read']::text[]) LOOP
 INSERT INTO role_permissions(role_id,permission) VALUES(next_role,permission_code) ON CONFLICT DO NOTHING;
 INSERT INTO staff_scope_grants(id,organisation_id,membership_id,capability,scope_kind,scope_id,inherit,effective_at) VALUES(business_s1224_uuidv7_seed(),item.organisation_id,item.member_id,permission_code,'COMPANY',item.organisation_id,true,now());
 END LOOP;
 UPDATE staff_memberships SET role_id=next_role,version=version+1,updated_at=now() WHERE id=item.member_id;
 INSERT INTO audit_events(id,organisation_id,action,target_type,target_id,change_context) VALUES(business_s1224_uuidv7_seed(),item.organisation_id,'SECTIONS1224_OWNER_CAPABILITY_MIGRATION','staff_membership',item.member_id,jsonb_build_object('from_role',item.id,'to_role',next_role,'version',next_version));
 END LOOP;
END;$$;
-- +goose StatementEnd
DROP FUNCTION business_s1224_uuidv7_seed();
-- +goose Down
-- Forward only; role versions and grants are immutable history.
SELECT 1;
